package com.aoo.bcg.common.repair;import com.aoo.bcg.common.recovery.*;import java.util.Objects;
/** Serializes an active-room correction behind the current lease and committed event sequence. */
public final class ActiveRoomRepairGuard{private final RoomLeaseStore leases;private final RoomSnapshotStore snapshots;public ActiveRoomRepairGuard(RoomLeaseStore leases,RoomSnapshotStore snapshots){this.leases=Objects.requireNonNull(leases);this.snapshots=Objects.requireNonNull(snapshots);}public long execute(RoomLease lease,long expectedEventSequence,RepairEventAppend append)throws Exception{Objects.requireNonNull(lease);Objects.requireNonNull(append);if(!leases.isCurrent(lease))throw new IllegalStateException("stale room repair lease");RoomSnapshot snapshot=snapshots.latest(lease.roomId()).orElseThrow(()->new IllegalArgumentException("room snapshot missing"));if(lease.fencingToken()<snapshot.fencingToken())throw new IllegalStateException("repair fencing token regressed");if(snapshot.lastEventSequence()!=expectedEventSequence)throw new IllegalStateException("repair event sequence conflict");long committed=append.append(lease.fencingToken(),expectedEventSequence+1);if(committed!=expectedEventSequence+1)throw new IllegalStateException("repair must append exactly one sequenced event");return committed;}@FunctionalInterface public interface RepairEventAppend{long append(long fencingToken,long nextEventSequence)throws Exception;}}
